/*
 * The ATRAC9 decoder's tables (0x8ebc8c-0x8f5834, 0x91ad38): the Huffman
 * codebooks of the scale factors and the spectra, the unit and band
 * tables, the dequantisation factors and the gradient curves.
 *
 * A scalar codebook looks up the next `width` bits in its table for a
 * symbol; the length of the code is lengths[symbol] (from the middle of an
 * array of signed symbols). A vector codebook looks them up for a record
 * number; the record is the code's length and its values.
 */
